+                sendButton.setEnabled(true);
+            }
+        });
+        phoneField.addValueChangeListener(e -> {
+            if (!sendButton.isEnabled()) {
+                sendButton.setEnabled(true);
+            }
+        });
+        messageField.addValueChangeListener(e -> {
+            if (!sendButton.isEnabled()) {
+                sendButton.setEnabled(true);
+            }
+        });
+
+        sendButton.addClickListener(e -> handleSend());
+        messageField.addKeyDownListener(com.vaadin.flow.component.Key.ENTER,
+                e -> {
+                    if (sendButton.isEnabled()) {
+                        handleSend();
+                    }
+                });
+
+        add(nameField, emailField, phoneField, messageField, sendButton);
+    }
+
+    private void handleSend() {
+        Message message = new Message(
+                nameField.getValue(),
+                emailField.getValue(),
+                phoneField.getValue(),
+                messageField.getValue()
+        );
+
+        // Validate
+        List<String> errors = new ArrayList<>();
+
+        if (nameField.getValue().trim().isEmpty()) {
+            nameField.setInvalid(true);
+            nameField.setErrorMessage("Name is required");
+            errors.add("name");
+        } else {
+            nameField.setInvalid(false);
+        }
+
+        // Email validation
+        String emailValue = emailField.getValue().trim();
+        String phoneValue = phoneField.getValue().trim();
+
+        boolean emailInvalid = false;
+        if (!emailValue.isEmpty() && !isValidEmail(emailValue)) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            errors.add("email");
+            emailInvalid = true;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            errors.add("email");
+            emailInvalid = true;
+        } else {
+            emailField.setInvalid(false);
+        }
+
+        if (messageField.getValue().trim().isEmpty()) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message is required");
+            errors.add("message");
+        } else if (messageField.getValue().length() > 500) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            errors.add("message");
+        } else {
+            messageField.setInvalid(false);
+        }
+
+        if (errors.isEmpty()) {
+            // Add to messages list
+            messages.add(0, message); // Add to front (newest first)
+            grid.setItems(messages);
+
+            // Show notification
+            Notification.show("Message sent");
+
+            // Clear fields
+            nameField.clear();
+            emailField.clear();
+            phoneField.clear();
+            messageField.clear();
+
+            // Disable send button
+            sendButton.setEnabled(false);
+        }
+    }
+
+    private boolean isValidEmail(String email) {
+        if (!email.contains("@")) return false;
+        String[] parts = email.split("@");
+        if (parts.length != 2) return false;
+        if (parts[0].isEmpty() || parts[1].isEmpty()) return false;
+        return parts[1].contains(".");
+    }
+
+    private void setupGrid() {
+        grid = new Grid<>(Message.class, false);
+        grid.addColumn(Message::getName).setHeader("Name");
+        grid.addColumn(Message::getText).setHeader("Message");
+        grid.setItems(messages);
+        add(grid);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        boolean hasContent = !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+
+        if (hasContent) {
+            event.postpone();
+
+            Dialog dialog = new Dialog();
+            dialog.setHeaderTitle("Unsaved changes");
+
+            VerticalLayout content = new VerticalLayout();
+            content.add("You have unsaved changes. Do you want to discard them?");
+
+            Button keepEditing = new Button("Keep editing", e -> dialog.close());
+            Button discard = new Button("Discard", e -> {
+                dialog.close();
+                event.forwardTo(AboutView.class);
+            });
+
+            content.add(keepEditing, discard);
+            dialog.add(content);
+            dialog.open();
+        }
+    }
+}
